import {lessons,mermaidSource} from './lessons.js';
const $=selector=>document.querySelector(selector);
const NS='http://www.w3.org/2000/svg';
const IDS=['concepts','reuse','query','validate','reason','plan'];
let data=null;
let state={lesson:'concepts',step:0,all:false,fit:false,validation:'valid',reasoned:false};
let sourceChoice='public';
function readURL(){const q=new URLSearchParams(location.search);state={...state,lesson:IDS.includes(q.get('lesson'))?q.get('lesson'):'concepts',step:Math.max(0,Math.min(6,(Number.parseInt(q.get('step'),10)||1)-1)),all:q.get('all')==='1',fit:q.get('fit')==='1',validation:['valid','invented','wrongtype'].includes(q.get('proposal'))?q.get('proposal'):'valid',reasoned:q.get('reasoned')==='1'};}
function syncURL(){const q=new URLSearchParams({lesson:state.lesson,step:String(state.step+1)});if(state.all)q.set('all','1');if(state.fit)q.set('fit','1');if(state.lesson==='validate')q.set('proposal',state.validation);if(state.lesson==='reason'&&state.reasoned)q.set('reasoned','1');history.pushState(null,'','?'+q.toString());}
function current(){return lessons(data,state).find(l=>l.id===state.lesson);}
function setState(next,push=true){state={...state,...next};const n=current().messages.length;state.step=Math.min(state.step,n-1);if(push)syncURL();render();}
function svgElement(tag,attrs={},text){const e=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,String(v));if(text!==undefined)e.textContent=text;return e;}
function escapeHTML(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function control(text,active,callback){const b=document.createElement('button');b.className='control-chip'+(active?' active':'');b.textContent=text;b.dataset.focus=text;b.setAttribute('aria-pressed',String(active));b.addEventListener('click',callback);return b;}
function controls(lesson){const root=$('#lesson-controls');root.replaceChildren();if(lesson.id==='validate'){const label=document.createElement('span');label.className='control-label';label.textContent='Proposal';root.append(label);for(const[id,label]of [['valid','Valid facts'],['invented','Invented field'],['wrongtype','Wrong value type']])root.append(control(label,state.validation===id,()=>setState({validation:id,step:0})));}else if(lesson.id==='reason'){root.append(control(state.reasoned?'Reset reasoning replay':'Replay recorded reasoning',state.reasoned,()=>{setState({reasoned:!state.reasoned,step:!state.reasoned?1:0});focusMessage();}));}else{const mode=document.createElement('p');mode.className='lesson-mode';mode.innerHTML='<span class="dot">●</span>'+escapeHTML(lesson.mode);root.append(mode);}}
function participantLabel(group,name,x,y){const words=name.split(' ');let lines=[name];if(name.length>17){const split=Math.ceil(words.length/2);lines=[words.slice(0,split).join(' '),words.slice(split).join(' ')];}lines.forEach((line,i)=>group.append(svgElement('text',{x,y:y+(i-(lines.length-1)/2)*14,class:'participant-name','text-anchor':'middle'},line)));}
function draw(lesson){const graph=$('#graph');const viewport=$('#graph-container');const count=lesson.participants.length;const width=Math.max(620,Math.round(viewport.clientWidth),count*170+30);const left=80,right=width-70;const gap=(right-left)/(count-1);const xs=Object.fromEntries(lesson.participants.map((p,i)=>[p.id,left+i*gap]));const row=76,first=127,end=first+(lesson.messages.length-1)*row+61,height=end+50;
 graph.setAttribute('viewBox',`0 0 ${width} ${height}`);graph.setAttribute('height',height);graph.style.width=width+'px';graph.style.height=height+'px';viewport.classList.toggle('fit',state.fit);
 graph.replaceChildren(svgElement('title',{id:'graph-title'},lesson.title),svgElement('desc',{id:'graph-desc'},'Participant sequence diagram. Read messages from top to bottom. '+lesson.description));
 const defs=svgElement('defs');for(const[id,color]of [['normal','#8ba496'],['active','#167269'],['failed','#ab4c4c']]){const marker=svgElement('marker',{id:'sequence-arrow-'+id,viewBox:'0 0 10 10',refX:9,refY:5,markerWidth:7,markerHeight:7,orient:'auto'});marker.append(svgElement('path',{d:'M 1 1 L 9 5 L 1 9',fill:'none',stroke:color,'stroke-width':1.5}));defs.append(marker);}graph.append(defs);
 graph.append(svgElement('text',{x:18,y:89,class:'sequence-time',transform:'rotate(90 18 89)'},'TIME ↓'));
 for(const p of lesson.participants){const x=xs[p.id];graph.append(svgElement('line',{x1:x,y1:63,x2:x,y2:end,class:'lifeline'}));const g=svgElement('g',{'aria-label':p.name+', '+p.kind});g.append(svgElement('rect',{x:x-62,y:10,width:124,height:54,rx:6,class:'participant-box'+(p.id==='oo'?' engine':'')}));participantLabel(g,p.name,x,31);g.append(svgElement('text',{x,y:55,class:'participant-kind','text-anchor':'middle'},p.kind));graph.append(g);graph.append(svgElement('rect',{x:x-52,y:end,width:104,height:26,rx:4,class:'participant-bottom'}));graph.append(svgElement('text',{x,y:end+17,'text-anchor':'middle',class:'participant-kind'},p.name));}
 lesson.messages.forEach((m,i)=>{const y=first+i*row;const active=i===state.step;const g=svgElement('g',{class:'sequence-message'+(active?' selected':'')+(!state.all&&i>state.step?' upcoming':'')+(m.reply?' reply':'')+(m.failed?' failed':''),tabindex:0,role:'button','data-message':i,'aria-label':`Message ${i+1}. ${m.from} to ${m.to}. ${m.label}. ${m.title}`,'aria-pressed':String(active)});g.append(svgElement('rect',{x:4,y:y-42,width:width-8,height:66,rx:5,class:'sequence-hit'}));g.append(svgElement('circle',{cx:29,cy:y-2,r:10,class:'message-number-circle'}));g.append(svgElement('text',{x:29,y:y+1,'text-anchor':'middle',class:'message-number'},i+1));const start=xs[m.from],finish=xs[m.to];const self=m.from===m.to;let path,labelX;
  if(self){const bend=start+70;path=`M ${start} ${y-12} L ${bend} ${y-12} L ${bend} ${y+10} L ${start+1} ${y+10}`;labelX=start+75;}else{path=`M ${start} ${y} L ${finish} ${y}`;labelX=(start+finish)/2;}
  const marker=m.failed?'failed':active?'active':'normal';g.append(svgElement('path',{d:path,class:'message-arrow','marker-end':'url(#sequence-arrow-'+marker+')'}));g.append(svgElement('text',{x:labelX,y:y-(self?23:12),'text-anchor':self?'start':'middle',class:'message-label'},m.label));const activate=()=>{setState({step:i});};g.addEventListener('click',activate);g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();activate();}});graph.append(g);});
 $('#map-caption').textContent=viewport.clientWidth<620?'Swipe sideways to follow participants. Time flows down.':'Time flows down. Select a message to inspect the library operation.';$('#graph-key').textContent='— Request   ┄ Reply';
}
function inspect(lesson){const m=lesson.messages[state.step];$('#inspector').className='inspector';$('#inspector').innerHTML=`<div class="inspector-overline"><span>MESSAGE ${state.step+1} / ${lesson.messages.length}</span><span>${m.failed?'CHECK FAILED':'EXCHANGE'}</span></div><span class="type-pill">${escapeHTML(lesson.participants.find(p=>p.id===m.from)?.name||m.from)} → ${escapeHTML(lesson.participants.find(p=>p.id===m.to)?.name||m.to)}</span><h3>${escapeHTML(m.title)}</h3><p class="body">${escapeHTML(m.body)}</p><div class="operation-label">OPERATION OR MODELING STEP</div><span class="operation-pill">${escapeHTML(m.operation)}</span>${m.code?'<pre tabindex="0">'+escapeHTML(m.code)+'</pre>':''}<div class="message-result${m.failed?' failure':''}">${escapeHTML(m.result)}</div>${m.source?'<a class="public-source" target="_blank" rel="noopener" href="'+escapeHTML(m.source)+'">Read the public definition ↗</a>':''}<div class="agent-tip"><strong>FOLLOW THE SEQUENCE</strong><ol class="message-list">${lesson.messages.map((x,i)=>'<li><button data-inspect-step="'+i+'" class="'+(i===state.step?'active':'')+'">'+(i+1)+'. '+escapeHTML(x.label)+'</button></li>').join('')}</ol></div>`;for(const b of document.querySelectorAll('[data-inspect-step]'))b.addEventListener('click',()=>{setState({step:Number(b.dataset.inspectStep)});focusMessage();});}
function focusMessage(){const node=document.querySelector(`[data-message="${state.step}"]`);if(!node)return;node.scrollIntoView({block:'nearest',inline:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
function render(){if(!data)return;const l=current();state.step=Math.min(Math.max(state.step,0),l.messages.length-1);const active=document.activeElement;const focus=active?.dataset?.focus;const message=active?.dataset?.message;$('#lesson-kicker').textContent=l.kicker;$('#lesson-title').textContent=l.title;$('#lesson-description').textContent=l.description;for(const b of document.querySelectorAll('[data-lesson]')){if(b.dataset.lesson===l.id)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');}controls(l);draw(l);inspect(l);$('#takeaway').className='takeaway';$('#takeaway').innerHTML='<span class="bulb" aria-hidden="true">◇</span><div><strong>'+escapeHTML(l.takeTitle)+'</strong><p>'+escapeHTML(l.take)+'</p></div>';$('#step-counter').textContent=`Message ${state.step+1} of ${l.messages.length}`;$('#step-back').disabled=state.step===0;$('#step-next').disabled=state.step===l.messages.length-1;$('#show-all').setAttribute('aria-pressed',String(state.all));$('#show-all').textContent=state.all?'Step focus':'Show all';$('#fit-diagram').setAttribute('aria-pressed',String(state.fit));$('#fit-diagram').textContent=state.fit?'100%':'Fit';const index=IDS.indexOf(l.id);$('#previous').disabled=index===0;$('#next').textContent=index===IDS.length-1?'Start again ↺':'Next lesson →';$('#progress').textContent=`LESSON ${index+1} OF ${IDS.length}`;if($('#source-details').open&&sourceChoice==='diagram')showSource('diagram');if(focus)for(const b of document.querySelectorAll('[data-focus]'))if(b.dataset.focus===focus)b.focus({preventScroll:true});if(message)document.querySelector(`[data-message="${message}"]`)?.focus({preventScroll:true});}
function goLesson(id){setState({lesson:id,step:0,all:false});$('#graph-container').scrollLeft=0;document.querySelector(`[data-lesson="${id}"]`).scrollIntoView({block:'nearest',inline:'nearest'});}
function showSource(kind){sourceChoice=kind;for(const b of document.querySelectorAll('[data-source]'))b.classList.toggle('active',b.dataset.source===kind);$('#source-code').textContent=kind==='results'?JSON.stringify(data.results,null,2):kind==='diagram'?mermaidSource(current()):data[kind]||'Source unavailable.';}
for(const b of document.querySelectorAll('[data-lesson]'))b.addEventListener('click',()=>goLesson(b.dataset.lesson));
for(const b of document.querySelectorAll('[data-source]'))b.addEventListener('click',()=>showSource(b.dataset.source));
$('#source-details').addEventListener('toggle',()=>{if($('#source-details').open&&data)showSource(sourceChoice);});
$('#step-back').addEventListener('click',()=>{setState({step:Math.max(0,state.step-1)});focusMessage();});
$('#step-next').addEventListener('click',()=>{setState({step:Math.min(current().messages.length-1,state.step+1)});focusMessage();});
$('#show-all').addEventListener('click',()=>setState({all:!state.all}));
$('#fit-diagram').addEventListener('click',()=>setState({fit:!state.fit}));
$('#previous').addEventListener('click',()=>goLesson(IDS[Math.max(0,IDS.indexOf(state.lesson)-1)]));
$('#next').addEventListener('click',()=>goLesson(IDS[(IDS.indexOf(state.lesson)+1)%IDS.length]));
$('#reset-view').addEventListener('click',()=>{setState({step:0,all:false,fit:false,validation:'valid',reasoned:false});$('#graph-container').scrollLeft=0;});
window.addEventListener('popstate',()=>{readURL();render();});
let frame;new ResizeObserver(()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{if(data)draw(current());});}).observe($('#graph-container'));
async function start(){try{const response=await fetch('/data.json');if(!response.ok)throw new Error('HTTP '+response.status);data=await response.json();readURL();render();}catch(error){$('#lesson-title').textContent='The lab could not load.';$('#lesson-description').textContent='Reload the page or download the runnable example.';$('#step-counter').textContent='Data unavailable';}}
start();
